# Inglés I–IV: inglés de negocios con Market Leader (Cotton, Falvey y Kent). Cada unidad: tema, vocabulario, gramática y expresiones útiles.
def ex(*pairs):
    return "<div class=\"tbl\"><table><tr><th>English</th><th>Español</th></tr>" + "".join(f"<tr><td><i>{a}</i></td><td>{b}</td></tr>" for a, b in pairs) + "</table></div>"
def unit(sid,u,t,tema,voc,gram,frases):
    return (sid,u,t,"tarjetas",[("Tema",p(tema)),("Vocabulario clave",ex(*voc)),("Gramática",gram),("Frases útiles",ul(*frases))])
